s los resultados y el propietario decide si continúa, se ajusta la estrategia o se termina el acuerdo","informe_mensual":true,"beneficios":[],"video_url":null,"video_minutos":3,"acuerdo_url":null}},"seguimiento":{"dias_tras_pensarlo":2,"horas_para_aliado":72}}'::jsonb) on conflict (slug) do update set nombre = excluded.nombre, zona_horaria = excluded.zona_horaria, mercado = excluded.mercado, parametros = excluded.parametros;
