¿Cuál prefieres?', false) on conflict (tenant_id, clave) where rol_codigo is null do update set texto = excluded.texto, requiere_aprobacion_meta = excluded.requiere_aprobacion_meta;
insert into app.plantillas (tenant_id, rol_codigo, clave, texto, requiere_aprobacion_meta) values ((select id from app.tenants where slug = 'javier-nunez'), null, 'horarios_preferencia_sin_cupo', 'Para el {{dia}} no hay horarios disponibles. Estas son las opciones más cercanas (hora de Colombia):
{{horarios_disponibles}}
