insert into app.plantillas (tenant_id, rol_codigo, clave, texto, requiere_aprobacion_meta) values ((select id from app.tenants where slug = 'javier-nunez'), null, 'falla_agenda', 'No fue posible confirmar la reserva en este momento. Tu información quedó registrada, pero el horario aún no está reservado.', false) on conflict (tenant_id, clave) where rol_codigo is null do update set texto = excluded.texto, requiere_aprobacion_meta = excluded.requiere_aprobacion_meta;
insert into app.plantillas (tenant_id, rol_codigo, clave, texto, requiere_aprobacion_meta) values ((select id from app.tenants where slug = 'javier-nunez'), 'lucia', 'propuesta', 'Perfecto, {{nombre}}. Ya tenemos toda la información. Antes de avanzar con la llamada con {{asesor}}, queremos comentarte que {{asesor}} trabaja las propiedades en exclusiva y con una comisión del {{comision_pct}} %. No garantizamos el precio ni el plazo de venta. ¿Hay algo que quieras aclarar antes de continuar?', false) on conflict (tenant_id, rol_codigo, clave) where rol_codigo is not null do update set texto = excluded.texto, requiere_aprobacion_meta = excluded.requiere_aprobacion_meta;
insert into app.plantillas (tenant_id, rol_codigo, clave, texto, requiere_aprobacion_meta) values ((select id from app.tenants where slug = 'javier-nunez'), 'lucia', 'propuesta_video', 'Perfecto, {{nombre}}, gracias por tomarte el tiempo de responderme. {{asesor}} trabaja las propiedades en exclusiva y con una comisión del {{comision_pct}} %; no garantizamos el precio ni el plazo de venta. Para que veas cómo trabajamos, te comparto un video de {{video_minutos}} minutos con nuestro proceso paso a paso: {{video_url}} ¿Hay algo que quieras aclarar antes de continuar?', false) on conflict (tenant_id, rol_codigo, clave) where rol_codigo is not null do update set texto = excluded.texto, requiere_aprobacion_meta = excluded.requiere_aprobacion_meta;
insert into app.plantillas (tenant_id, rol_codigo, clave, texto, requiere_aprobacion_meta) values ((select id from app.tenants where slug = 'javier-nunez'), 'lucia', 'solo_venta', 'Gracias por escribirnos. {{asesor}} se dedica a la venta de inmuebles y no maneja propiedades solo para arriendo, así que no podríamos ayudarte con eso. Si en algún momento consideras vender tu propiedad, con gusto te asesoramos.', false) on conflict (tenant_id, rol_codigo, clave) where rol_codigo is not null do update set texto = excluded.texto, requiere_aprobacion_meta = excluded.requiere_aprobacion_meta;
insert into app.plantillas (tenant_id, rol_codigo, clave, texto, requiere_aprobacion_meta) values ((select id from app.tenants where slug = 'javier-nunez'), 'lucia', 'fuera_cobertura', 'Gracias por contarme. {{asesor}} atiende directamente propiedades en {{ciudades_cobertura}}, y prefiero ser honesta contigo para que no pierdas tiempo. Podemos consultar si un colega de nuestra confianza atiende esa zona, sin ningún costo adicional para ti. ¿Nos autorizas a compartir tus datos de contacto y la información de la propiedad para gestionar esa posible referencia?', false) on conflict (tenant_id, rol_codigo, clave) where rol_codigo is not null do update set texto = excluded.texto, requiere_aprobacion_meta = excluded.requiere_aprobacion_meta;
insert into app.plantillas (tenant_id, rol_codigo, clave, texto, requiere_aprobacion_meta) values ((select id from app.tenants where slug = 'javier-nunez'), 'lucia', 'fuera_cobertura_barrio', 'Gracias. Ese sector no es una de las zonas que {{asesor}} atiende directamente, y prefiero ser honesta contigo para que no pierdas tiempo. Podemos consultar si un colega de nuestra confianza que conoce bien esa zona puede atenderte, sin ningún costo adicional para ti. ¿Nos autorizas a compartir tus datos de contacto y la información de la propiedad para gestionar esa posible referencia?', false) on conflict (tenant_id, rol_codigo, clave) where rol_codigo is not null do update set texto = excluded.texto, requiere_aprobacion_meta = excluded.requiere_aprobacion_meta;
insert into app.plantillas (tenant_id, rol_codigo, clave, texto, requiere_aprobacion_meta) values ((select id from app.tenants where slug = 'javier-nunez'), 'lucia', 'referencia_valor', 'Gracias por el dato. {{asesor}} concentra su trabajo directo en propiedades de un rango de valor distinto, y prefiero ser clara contigo. Podemos consultar si un colega aliado de nuestra confianza, que trabaja con propiedades de ese rango, puede atenderte. ¿Nos autorizas a compartir tus datos de contacto y la información de la propiedad para gestionar esa posible referencia?', false) on conflict (tenant_id, rol_codigo, clave) where rol_codigo is not null do update set texto = excluded.texto, requiere_aprobacion_meta = excluded.requiere_aprobacion_meta;
insert into app.plantillas (tenant_id, rol_codigo, clave, texto, requiere_aprobacion_meta) values ((select id from app.tenants where slug = 'javier-nunez'), null, 'no_calificado', 'Gracias por compartir la información. En este momento tu caso no cumple las condiciones necesarias para continuar con el proceso.', false) on conflict (tenant_id, clave) where rol_codigo is null do update set texto = excluded.texto, requiere_aprobacion_meta = excluded.requiere_aprobacion_meta;
insert into app.plantillas (tenant_id, rol_codigo, clave, texto, requiere_aprobacion_meta) values ((select id from app.tenants where slug = 'javier-nunez'), null, 'no_calificado_nutricion', 'Gracias por compartir la información. Por ahora no podemos avanzar con una llamada, pero quedas registrado y te compartiremos información útil para tu proceso. Cuando quieras retomar, escríbenos por aquí.', false) on conflict (tenant_id, clave) where rol_codigo is null do update set texto = excluded.texto, requiere_aprobacion_meta = excluded.requiere_aprobacion_meta;
insert into app.plantillas (tenant_id, rol_codigo, clave, texto, requiere_aprobacion_meta) values ((select id from app.tenants where slug = 'javier-nunez'), null, 'prioridad_baja', 'Gracias, ya tenemos la información que necesitamos. Como aún no tienes prisa, por ahora no agendaremos una llamada: quedas registrado y te compartiremos información útil para tu proceso. Cuando quieras avanzar, escríbenos por aquí.', false) on conflict (tenant_id, clave) where rol_codigo is null do update set texto = excluded.texto, requiere_aprobacion_meta = excluded.requiere_aprobacion_meta;
